insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--brentford', 'Brentford Football Club', 'Brentford', 'football', 'Premier League', 'England', 'London', 'Gtech Community Stadium', 17250, 'https://www.football-stadiums.co.uk/grounds/brentford-community-stadium/', 1889, 'brentfordfc.com', 'individual_family', 'Matthew Benham, who took full control in 2012, remains majority shareholder through holding company Best Intentions Analytics Limited (BIA), formed in February 2025 to hold his shares in Brentford FC and Spanish club Merida AD. Minority shareholders are Gary Lubner (via This Day Sports and Media Ltd) and Sir Matthew Vaughn (via MARV Bee Ltd) since July 2025, joined in March 2026 by Blackstone executive Prakash Melwani and Universal Music Group CEO Sir Lucian Grainge; stake sizes have not been disclosed by the club.', 'https://www.brentfordfc.com/en/news/club-news-brentford-announces-further-investment-prakash-melwani-sir-lucian-grainge-cbe', 173100000, 'GBP', '2024-25', 'Brentford FC (financial results for 2024/25 season)', 'https://www.brentfordfc.com/en/news/article/club-news-brentford-fc-financial-results-2024-25', 400000000, 'GBP', 2025, 'SportsPro (valuation implied by July 2025 minority stake sale)', 'https://www.sportspro.com/news/brentford-investment-gary-lubner-matthew-vaughn-benham-july-2025/', null, '2026-09-28', 'https://www.instagram.com/brentfordfc/', '[{"platform": "Instagram", "followers": 889000, "as_of": "2026-09-28", "source_url": "https://www.instagram.com/brentfordfc/"}, {"platform": "Facebook", "followers": 1800000, "as_of": "2026-09-28", "source_url": "https://www.facebook.com/brentfordfootballclub1889/"}, {"platform": "X", "followers": 228600, "as_of": "2026-09-28", "source_url": "https://www.speakrj.com/audit/report/BrentfordFC/twitter"}]'::jsonb, 'Stake sizes: the club has never disclosed the minority holdings. Non-authoritative sites (brandsownedby.com, whoistheownerof.com) state Benham 90%, Lubner 5%, Vaughn 5% as of late 2025, before the March 2026 round in which Lubner and Vaughn increased holdings and Melwani and Grainge entered; treat those percentages as unverified. SportsPro reported up to 25% could ultimately change hands. Valuation: the £400m figure is the valuation implied by the July 2025 minority sale (SportsPro; City AM), not a Forbes/Sportico estimate. Sportico''s 2026 list references the Brentford LP deal at about $540m and notes LP deals price below control valuations; Brentford does not appear in Forbes'' 2026 top 30. Deloitte Football Money League 2026 lists Brentford 30th with EUR 206m revenue for 2024-25 (club accounts state GBP 173.1m turnover, record, with operating loss before player trading of GBP 40.0m and player-trading profit of GBP 27.2m). Debt: GBP 100m Macquarie facility from July 2025 is reported by analysts of the 2024/25 accounts (The Esk, Swiss Ramble), not by a club press release found here. The holding company BIA also owns Spanish club Merida AD. Benham''s original takeover was June 2012 (before the 2015 window). Social total is null because no source states a cross-platform total; per-platform counts are as displayed on the pages on 2026-09-28.', '["https://www.brentfordfc.com/en/news/article/club-news-brentford-new-investment-gary-lubner-sir-matthew-vaughn", "https://www.brentfordfc.com/en/news/club-news-brentford-announces-further-investment-prakash-melwani-sir-lucian-grainge-cbe", "https://www.sportspro.com/news/brentford-investment-gary-lubner-matthew-vaughn-benham-july-2025/", "https://www.insideworldfootball.com/2025/07/16/lubner-vaughn-take-minority-stakes-brentford/", "https://www.bloomberg.com/news/articles/2026-03-02/brentford-fc-gets-investment-from-music-mogul-blackstone-exec", "https://www.proskauer.com/release/proskauer-represents-prakash-melwani-in-minority-investment-in-best-intentions-analytics-limited-holding-company-of-brentford-fc-and-mrida-ad", "https://www.brentfordfc.com/en/news/article/club-news-brentford-fc-financial-results-2024-25", "https://www.brentfordfc.com/en/news/article/club-news-brentford-financial-results-announced-30-06-2023", "https://theesk.org/2026/05/12/the-analysis-series-financial-analysis-of-brentford-football-club-consolidation-capital-restructuring-and-the-2024-25-fiscal-cycle/", "https://swissramble.substack.com/p/brentford-finances-202425", "https://football-finance-files.beehiiv.com/p/deloitte-s-football-money-league-trends-2026", "https://www.sportico.com/valuations/teams/2026/most-valuable-soccer-teams-2026-real-madrid-barcelona-1234890790/", "https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/", "https://www.football-stadiums.co.uk/grounds/brentford-community-stadium/", "https://www.instagram.com/brentfordfc/", "https://www.facebook.com/brentfordfootballclub1889/", "https://www.speakrj.com/audit/report/BrentfordFC/twitter", "https://brandsownedby.com/who-owns-brentford-fc/"]'::jsonb, '[]'::jsonb, 'web_research')
  on conflict (external_key) do update set name = excluded.name, short_name = excluded.short_name, sport = excluded.sport, league = excluded.league, country = excluded.country, city = excluded.city, stadium = excluded.stadium, stadium_capacity = excluded.stadium_capacity, stadium_capacity_source_url = excluded.stadium_capacity_source_url, founded_year = excluded.founded_year, domain = excluded.domain, ownership_type = excluded.ownership_type, ownership_summary = excluded.ownership_summary, ownership_source_url = excluded.ownership_source_url, revenue = excluded.revenue, revenue_currency = excluded.revenue_currency, revenue_season = excluded.revenue_season, revenue_source_name = excluded.revenue_source_name, revenue_source_url = excluded.revenue_source_url, valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, valuation_year = excluded.valuation_year, valuation_source_name = excluded.valuation_source_name, valuation_source_url = excluded.valuation_source_url, social_followers = excluded.social_followers, social_as_of = excluded.social_as_of, social_source_url = excluded.social_source_url, social_platforms = excluded.social_platforms, notes = excluded.notes, sources = excluded.sources, verification = excluded.verification, source = excluded.source;
